import{_ as e,o as d,c as s,ag as r}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Réglages","description":"","frontmatter":{},"headers":[],"relativePath":"fr/car-wash/settings.md","filePath":"fr/car-wash/settings.md"}'),a={name:"fr/car-wash/settings.md"};function o(n,t,i,l,c,u){return d(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="reglages" tabindex="-1">Réglages <a class="header-anchor" href="#reglages" aria-label="Permalink to &quot;Réglages&quot;">​</a></h1><p>Chaque réglage du Car Wash se modifie dans <code>/nay</code>, sur la page <strong>Car Wash</strong> (scope <code>nay_car_wash.config</code>). Les changements sont enregistrés dans la base et appliqués tout de suite à tous les joueurs. <code>config.lua</code> contient des valeurs de départ facultatives : elles s&#39;appliquent tant qu&#39;un réglage n&#39;a pas été changé dans <code>/nay</code>, et <strong>Réinitialiser</strong> revient à elles.</p><p>La colonne <strong>Dans /nay</strong> donne le nom affiché dans le panneau. La clé est le nom utilisé par <code>config.lua</code> et par l&#39;<a href="/fr/nay-lib/api">API HTTP</a>.</p><h2 id="general" tabindex="-1">Général <a class="header-anchor" href="#general" aria-label="Permalink to &quot;Général&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Activé</td><td><code>Enabled</code></td><td>oui / non</td><td>oui</td><td>Active ou désactive tous les tunnels et nettoyeurs.</td></tr><tr><td>Interaction à pied</td><td><code>InteractionMode</code></td><td><code>key</code> ou <code>target</code></td><td><code>key</code></td><td>Comment les joueurs lancent un nettoyeur : invite de touche (E) ou œil de target. Les tunnels utilisent toujours E depuis le véhicule.</td></tr><tr><td>Compte de paiement</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> ou <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Où le prix est prélevé. <code>cash_then_bank</code> passe par la banque quand le liquide manque.</td></tr><tr><td>Remises par métier</td><td><code>JobDiscounts</code></td><td>liste, jusqu&#39;à 32</td><td>aucune</td><td>Remises pour un métier à partir d&#39;un grade, sur les tunnels et les nettoyeurs.</td></tr></tbody></table><p>Entrées de <strong>Remises par métier</strong> :</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Métier</td><td><code>Job</code></td><td>texte, 1 à 32 caractères</td><td>Nom du métier, comme dans votre framework.</td></tr><tr><td>Grade minimum</td><td><code>MinGrade</code></td><td>nombre, 0 à 100</td><td>Grade le plus bas qui a la remise.</td></tr><tr><td>Remise (%)</td><td><code>Percent</code></td><td>nombre, 1 à 100</td><td>Remise en pourcentage. 100 rend le lavage gratuit.</td></tr></tbody></table><h2 id="tunnels" tabindex="-1">Tunnels <a class="header-anchor" href="#tunnels" aria-label="Permalink to &quot;Tunnels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Formules de lavage</td><td><code>Programs</code></td><td>liste, 1 à 8</td><td>Express 150 $, Standard 250 $, Premium 400 $</td><td>Formules proposées dans chaque tunnel.</td></tr><tr><td>Tunnels</td><td><code>Tunnels</code></td><td>liste, jusqu&#39;à 32</td><td>Strawberry, Little Seoul</td><td>Les tunnels. Placés avec l&#39;<a href="/fr/car-wash/tunnels">éditeur de tunnels</a>.</td></tr><tr><td>Largeur maximale du véhicule (m)</td><td><code>MaxVehicleWidth</code></td><td>mètres, 1 à 6</td><td>2,25</td><td>Les véhicules plus larges sont refusés.</td></tr><tr><td>Classes de véhicules refusées</td><td><code>BlockedClasses</code></td><td>liste de classes de véhicules</td><td>motos, vélos, bateaux, hélicoptères, avions, trains</td><td>Classes de véhicules refusées à l&#39;entrée.</td></tr><tr><td>Refuser les véhicules propres</td><td><code>RequireDirt</code></td><td>oui / non</td><td>non</td><td>Refuse les véhicules déjà propres.</td></tr><tr><td>Remplacer les IPL des stations de la carte</td><td><code>ReplaceMapIpls</code></td><td>oui / non</td><td>oui</td><td>À Strawberry, remplace la station d&#39;origine par sa version sans brosses. Désactivez-le si une carte personnalisée ou un gestionnaire de mapping s&#39;occupe de cette station.</td></tr></tbody></table><p>Entrées de <strong>Formules de lavage</strong> :</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Nom</td><td><code>Label</code></td><td>texte, 1 à 32 caractères</td><td>Nom affiché dans le menu de lavage.</td></tr><tr><td>Prix</td><td><code>Price</code></td><td>nombre, 0 à 1000000</td><td>Prix avant remises et pourcentage du tunnel.</td></tr><tr><td>Vitesse (%)</td><td><code>SpeedPercent</code></td><td>nombre, 25 à 300</td><td>Vitesse relative à celle du tunnel.</td></tr><tr><td>Savon</td><td><code>Soap</code></td><td>oui / non</td><td>Lance l&#39;arche de savon.</td></tr><tr><td>Rinçage</td><td><code>Rinse</code></td><td>oui / non</td><td>Lance l&#39;arche de rinçage.</td></tr><tr><td>Séchage</td><td><code>Dry</code></td><td>oui / non</td><td>Lance le séchoir.</td></tr><tr><td>Cire (minutes)</td><td><code>WaxMinutes</code></td><td>nombre, 0 à 1440</td><td>Minutes pendant lesquelles le véhicule reste propre après le lavage. 0 signifie sans cire.</td></tr></tbody></table><p>Les entrées de <strong>Tunnels</strong> se modifient plus facilement avec l&#39;<a href="/fr/car-wash/tunnels">éditeur de tunnels</a>, qui remplit ces champs pour vous :</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Nom</td><td><code>Label</code></td><td>texte, jusqu&#39;à 48 caractères</td><td>Titre du menu de lavage, aussi utilisé dans l&#39;historique et les webhooks. Facultatif.</td></tr><tr><td>Ouvert</td><td><code>Enabled</code></td><td>oui / non</td><td>Ferme un tunnel sans le supprimer.</td></tr><tr><td>Entrée</td><td><code>Entry</code></td><td>position et orientation</td><td>Là où le conducteur s&#39;arrête et appuie sur E.</td></tr><tr><td>Début de ligne</td><td><code>Start</code></td><td>position</td><td>Début de la ligne suivie par le véhicule.</td></tr><tr><td>Fin de ligne</td><td><code>Finish</code></td><td>position</td><td>Fin de la ligne.</td></tr><tr><td>Largeur (m)</td><td><code>Width</code></td><td>mètres, 2 à 10</td><td>Largeur de la voie : dimensionne les arches, limite la largeur du véhicule (marge de 0,5 m) et sert au contrôle de voie bloquée.</td></tr><tr><td>Vitesse (m/s)</td><td><code>Speed</code></td><td>mètres par seconde, 0,5 à 8</td><td>Vitesse de base dans le tunnel, multipliée par la vitesse de la formule.</td></tr><tr><td>Prix (%)</td><td><code>PricePercent</code></td><td>nombre, 0 à 1000</td><td>Pourcentage appliqué à chaque prix de formule dans ce tunnel. 100 garde les prix.</td></tr><tr><td>Arche savon</td><td><code>SoapJet</code></td><td>position</td><td>Arche de savon.</td></tr><tr><td>Brosse haute</td><td><code>HorizontalRoller</code></td><td>position</td><td>Brosse du haut.</td></tr><tr><td>Brosses latérales</td><td><code>VerticalRoller</code></td><td>position</td><td>Brosses des côtés.</td></tr><tr><td>Arche rinçage</td><td><code>RinseJet</code></td><td>position</td><td>Arche de rinçage.</td></tr><tr><td>Séchoir</td><td><code>Dryer</code></td><td>position</td><td>Séchoir à vapeur. Facultatif.</td></tr></tbody></table><p>Les entrées de <strong>Classes de véhicules refusées</strong> ont un seul champ, <strong>Classe</strong> (<code>Class</code>), choisi par nom parmi les classes de véhicules de GTA.</p><h2 id="nettoyeurs-haute-pression" tabindex="-1">Nettoyeurs haute pression <a class="header-anchor" href="#nettoyeurs-haute-pression" aria-label="Permalink to &quot;Nettoyeurs haute pression&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Nettoyeurs haute pression</td><td><code>ManualEnabled</code></td><td>oui / non</td><td>oui</td><td>Active ou désactive les nettoyeurs.</td></tr><tr><td>Props de nettoyeur</td><td><code>ManualModels</code></td><td>liste, jusqu&#39;à 16</td><td><code>prop_gas_airunit01</code></td><td>Props du monde qui deviennent des nettoyeurs, partout où la carte en a.</td></tr><tr><td>Nettoyeurs placés</td><td><code>ManualStations</code></td><td>liste, jusqu&#39;à 64</td><td>aucun</td><td>Les nettoyeurs que vous placez vous-même.</td></tr><tr><td>Prix par niveau de saleté</td><td><code>ManualPricePerLevel</code></td><td>nombre, 0 à 100000</td><td>15</td><td>Prix d&#39;un niveau de saleté, avant remises par métier.</td></tr><tr><td>Secondes par niveau de saleté</td><td><code>ManualSecondsPerLevel</code></td><td>secondes, 0,2 à 10</td><td>1</td><td>Temps pour nettoyer un niveau de saleté.</td></tr></tbody></table><p>Les entrées de <strong>Props de nettoyeur</strong> ont un seul champ, <strong>Nom du modèle</strong> (<code>Model</code>) : le nom du modèle de prop (lettres, chiffres et tirets bas).</p><p>Entrées de <strong>Nettoyeurs placés</strong> :</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Nom</td><td><code>Label</code></td><td>texte, jusqu&#39;à 48 caractères</td><td>Nom de la station, utilisé dans l&#39;historique et les webhooks. Facultatif.</td></tr><tr><td>Position</td><td><code>Coords</code></td><td>position et orientation</td><td>Là où elle se trouve. <strong>Utiliser ma position</strong> la remplit depuis l&#39;endroit où vous êtes.</td></tr></tbody></table><p>Plus de détails sur la page <a href="/fr/car-wash/pressure-washers">Nettoyeurs haute pression</a>.</p><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Afficher les blips</td><td><code>ShowBlips</code></td><td>oui / non</td><td>oui</td><td>Affiche les tunnels et, quand les nettoyeurs sont activés, les stations placées sur la carte.</td></tr><tr><td>Icône du blip</td><td><code>BlipSprite</code></td><td>icône de blip</td><td>100</td><td>Choisie dans une liste visuelle d&#39;icônes. Un numéro peut toujours être saisi pour un blip personnalisé.</td></tr><tr><td>Couleur du blip</td><td><code>BlipColor</code></td><td>couleur de blip</td><td>63</td><td>Choisie dans une liste visuelle de couleurs.</td></tr><tr><td>Taille du blip</td><td><code>BlipScale</code></td><td>0,2 à 2</td><td>0,8</td><td>Taille du blip.</td></tr></tbody></table>',22)])])}const m=e(a,[["render",o]]);export{p as __pageData,m as default};
